/**
 * Drizzle migration runner.
 *
 * Migrations are generated by `drizzle-kit generate` into `backend/drizzle`
 * and applied automatically at startup when `RUN_MIGRATIONS` is enabled.
 */
import { migrate } from 'drizzle-orm/better-sqlite3/migrator'
import { fileURLToPath } from 'node:url'

import type { DbHandle } from './client'

/** The default migrations folder (repository `backend/drizzle`). */
export const DEFAULT_MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url))

/** Applies all pending migrations. */
export function runMigrations(handle: DbHandle, folder = DEFAULT_MIGRATIONS_FOLDER): void {
  migrate(handle.db, { migrationsFolder: folder })
}
